<?php
use App\Accounts\DeviceAuth;
use App\Content\SubtitleService;
use App\Domain\{Access,Failure};
use App\Exports\ExportService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Route;
$contentUser=fn(Request $r)=>Access::user($r->session()->get('uid'));
Route::get('/api/admin/subtitles',function(Request $r)use($contentUser){$u=$contentUser($r);Access::admin($u);$v=$r->validate(['course_id'=>'nullable|integer|min:1','lesson_id'=>'nullable|integer|min:1','search'=>'nullable|string|max:200','edited'=>'in:all,yes,no','deleted'=>'in:active,only,all','kind'=>'in:all,source,translation','page'=>'integer|min:1|max:100000']);return app(SubtitleService::class)->adminList($u,$v);});
Route::patch('/api/lessons/{lesson}/subtitles',function(Request $r,int $lesson)use($contentUser){$v=$r->validate(['changes'=>'required|array|min:1|max:20','changes.*.unit_id'=>'required|integer|min:1','changes.*.expected_version'=>'required|integer|min:1','changes.*.text'=>'required|string|max:20000','idempotency_key'=>'required|uuid']);return app(SubtitleService::class)->revise($lesson,$contentUser($r),$v['changes'],$v['idempotency_key'],$r->session()->getId());});
Route::get('/api/lessons/{lesson}/subtitles/{unit}/history',fn(Request $r,int $lesson,int $unit)=>app(SubtitleService::class)->history($lesson,$unit,$contentUser($r),$r->session()->getId(),$r->filled('before_id')?(int)$r->input('before_id'):null));
Route::post('/api/lessons/{lesson}/subtitles/{unit}/restore',function(Request $r,int $lesson,int $unit)use($contentUser){$v=$r->validate(['revision_id'=>'nullable|integer|min:1','expected_version'=>'required|integer|min:1','idempotency_key'=>'required|uuid']);return app(SubtitleService::class)->restore($lesson,$unit,$contentUser($r),$v['revision_id']??null,$v['expected_version'],$v['idempotency_key'],$r->session()->getId());});
Route::patch('/api/admin/lessons/{lesson}/editing',function(Request $r,int $lesson)use($contentUser){$u=$contentUser($r);Access::admin($u);DeviceAuth::requireRecent($r);$v=$r->validate(['frozen'=>'required|boolean']);if($r->input('confirmed')!==true)throw new Failure('confirmation_required');app(SubtitleService::class)->freeze($lesson,$u,$v['frozen']);return ['editing_frozen'=>$v['frozen']];});
Route::delete('/api/admin/lessons/{lesson}/subtitles/{unit}',function(Request $r,int $lesson,int $unit)use($contentUser){$u=$contentUser($r);Access::admin($u);DeviceAuth::requireRecent($r);if($r->input('confirmed')!==true)throw new Failure('confirmation_required');return app(SubtitleService::class)->deletion($lesson,$unit,$u,true);});
Route::post('/api/admin/lessons/{lesson}/subtitles/{unit}/restore-deleted',function(Request $r,int $lesson,int $unit)use($contentUser){$u=$contentUser($r);Access::admin($u);DeviceAuth::requireRecent($r);if($r->input('confirmed')!==true)throw new Failure('confirmation_required');return app(SubtitleService::class)->deletion($lesson,$unit,$u,false);});
Route::post('/api/lessons/{lesson}/exports',function(Request $r,int $lesson)use($contentUser){$v=$r->validate(['format'=>'required|in:txt,md,srt,vtt','layout'=>'required|in:source,translation,bilingual','text_version'=>'required|in:current,original','idempotency_key'=>'required|uuid']);return ['export'=>app(ExportService::class)->create($lesson,$contentUser($r),$v,$r->session()->getId())];});
Route::get('/api/exports/{export}',fn(Request $r,string $export)=>['export'=>app(ExportService::class)->status($export,$contentUser($r),$r->session()->getId())]);
Route::post('/api/exports/{export}/retry',fn(Request $r,string $export)=>['export'=>app(ExportService::class)->retry($export,$contentUser($r),$r->session()->getId())]);
Route::get('/api/exports/{export}/file',function(Request $r,string $export)use($contentUser){$artifact=app(ExportService::class)->file($export,$contentUser($r),$r->session()->getId());return response()->download($artifact['path'],$artifact['filename'],['Content-Type'=>$artifact['mime'],'Cache-Control'=>'no-store','X-Content-Type-Options'=>'nosniff'])->setPrivate();});
